def count_Substrings(s):
    count = 0
    n = len(s)
    for i in range(n):
        current_sum = 0
        for j in range(i, n):
            current_sum += int(s[j])
            length = j - i + 1
            if current_sum == length:
                count += 1
    return count

if __name__ == "__main__":
    assert count_Substrings('112112') == 6

