def sequence(n):
    if n <= 0:
        return None
    seq = [1, 1]
    if n <= 2:
        return seq[n - 1]
    for i in range(2, n):
        sub_seq = seq[:i]
        count = 0
        target = sub_seq[-1]
        for j in range(len(sub_seq) - 1, -1, -1):
            if sub_seq[j] == target:
                count += 1
                if count == target:
                    break
        seq.append(count)
    return seq[n - 1]

