            if n % i == 0:
                s += i
                if i * i != n and i != 1:
                    s += n // i
        return s
    amicable_sum = 0
    for a in range(1, limit + 1):
        b = get_sum_of_divisors(a)
        if b > a and b <= limit:
            if get_sum_of_divisors(b) == a:
                amicable_sum += a + b
        elif b > a:
            if get_sum_of_divisors(b) == a:
                amicable_sum += a + b
