def find_length(s):
    max_diff = 0
    n = len(s)
    for i in range(n):
        zeros = 0
        ones = 0
        for j in range(i, n):
            if s[j] == '0':
                zeros += 1
            else:
                ones += 1
            max_diff = max(max_diff, abs(zeros - ones))
    return max_diff

