import math

def sum_common_divisors(a, b):
    gcd = math.gcd(a, b)
    total_sum = 0
    for i in range(1, int(math.sqrt(gcd)) + 1):
        if gcd % i == 0:
            total_sum += i
            if i * i != gcd:
                total_sum += gcd // i
    return total_sum

