def is_majority(arr, n, element):
    import bisect
    first_index = bisect.bisect_left(arr, element)
    if first_index == n or arr[first_index] != element:
        return False
    last_index = first_index + n // 2
    if last_index < n and arr[last_index] == element:
        return True
    return False

