def max_product(nums):
    if not nums:
        return 0

    n = len(nums)
    dp = list(nums)

    for i in range(n):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] * nums[i])

    return max(dp)

if __name__ == "__main__":
    assert max_product([3, 100, 4, 5, 150, 6]) == 3000

