import math

def sum_Of_product(n):
    total_sum = 0
    for r in range(n + 1):
        if r + 1 <= n:
            term = math.comb(n, r) * math.comb(n, r + 1)
            total_sum += term
    return total_sum

def removezero_ip(ip: str) -> str:
    parts = ip.split('.')
