def diff_even_odd(numbers):
    first_even = next((x for x in numbers if x % 2 == 0), None)
    first_odd = next((x for x in numbers if x % 2 != 0), None)
    if first_even is None or first_odd is None:
        return None
    return abs(first_even - first_odd)

