def largest_subset(nums):
    if not nums:
        return 0

    nums = sorted(list(set(nums)))
    n = len(nums)
    dp = [1] * n

    for i in range(n):
        for j in range(i):
            if nums[i] % nums[j] == 0:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

