def get_median(arr1, arr2, n):
    merged = []
    i = 0
    j = 0
    while i < n and j < n:
        if arr1[i] < arr2[j]:
            merged.append(arr1[i])
            i += 1
        else:
            merged.append(arr2[j])
            j += 1
    while i < n:
        merged.append(arr1[i])
        i += 1
    while j < n:
        merged.append(arr2[j])
        j += 1
    total_len = 2 * n
    if total_len % 2 == 0:
        mid1 = merged[total_len // 2 - 1]
        mid2 = merged[total_len // 2]
        return (mid1 + mid2) / 2.0
    else:
        return float(merged[total_len // 2])

