def pair_xor_Sum(arr, n):
    total_sum = 0
    for i in range(32):
        count_set_bits = 0
        for j in range(n):
            if (arr[j] & (1 << i)):
                count_set_bits += 1

        count_unset_bits = n - count_set_bits
        total_sum += (count_set_bits * count_unset_bits) * (1 << i)

    return total_sum

