def toggle_middle_bits(n):
    if n < 2:
        return n
    binary_str = bin(n)[2:]
    first_bit = binary_str[0]
    last_bit = binary_str[-1]
    middle_bits = binary_str[1:-1]
    toggled_middle = ''.join(('1' if b == '0' else '0' for b in middle_bits))
    result_str = first_bit + toggled_middle + last_bit
    return int(result_str, 2)

