import math

def find_Index(n):
    if n == 1:
        return 1

    lower_bound = 10**(n-1)

    # Triangular number formula: T_k = k(k+1)/2
    # k^2 + k - 2*T_k = 0
    # Using quadratic formula: k = (-1 + sqrt(1 + 8*T_k)) / 2

    k = math.ceil((-1 + math.sqrt(1 + 8 * lower_bound)) / 2)

    while True:
        triangular_number = k * (k + 1) // 2
        if triangular_number >= lower_bound:
            return k
        k += 1

if __name__ == "__main__":
    assert find_Index(2) == 4

