def count_reverse_pairs(string_list):
    count = 0
    used_indices = set()
    for i in range(len(string_list)):
        if i in used_indices:
            continue
        for j in range(i + 1, len(string_list)):
            if j not in used_indices and string_list[i] == string_list[j][::-1]:
                count += 1
                used_indices.add(i)
                used_indices.add(j)
                break
    return count

